def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Dijkstra's algorithm
    dist = [float('inf')] * n
    dist[s] = 0
    visited = [False] * n
    pq = [(0, s)]

    while pq:
        current_dist, u = pq.pop(0)
        if visited[u]:
            continue
        visited[u] = True
        if u == t:
            return current_dist
        for v, w in adj[u]:
            if dist[v] > current_dist + w:
                dist[v] = current_dist + w
                pq.append((dist[v], v))

    return -1

